nt formats\n# Maybe it's stored as Dec. 18 or similar\n\n# Search for elements containing both '1952' and '12/' \nfor i, element in enumerate(data['document']['elements']):\n    content = str(element.get('content', ''))\n    # Look for bills issued in December 1952\n    if ('Bill' in content or 'bill' in content) and '1952' in content:\n        # Look for 12/ in context\n        if re.search(r'12/[0-9]+/52', content):\n            print(f'Element {i}:')\n            # Extract relevant portion\n            matches = re.findall(r'.{0,100}12/[0-9]+/52.{0,100}', content)\n            for m in matches[:3]:\n                print(m)\n            print('---')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
