son'))\n\n# Let's examine all the tables more comprehensively\n# Find all tables with 'Outstanding' and 'issue date' columns\n\nfor i, element in enumerate(data['document']['elements']):\n    if element.get('type') == 'table':\n        content = str(element.get('content', ''))\n        # Look for tables with amount outstanding and issue date\n        if 'Amount out-standing' in content and 'Issue date' in content:\n            print(f'Found at element {i}')\n            # Extract all issue dates and amounts\n            rows = content.split('<tr>')\n            for row in rows:\n                if '<td>' in row and '</td>' in row:\n                    # Get first 3 cells (amount, maturity, issue date)\n                    cells = re.findall(r'<td[^>]*>([^<]+)</td>', row)\n                    if len(cells) >= 3:\n                        print(cells[:3])\n            print('---')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
